function setQRVisibility(root,hidden){
 root.classList.toggle("qr-page-hidden",hidden);
 for(const node of [...root.querySelectorAll('img.qr-private, img.qr-private-cover')]){
  if(hidden&&node.classList.contains('qr-private')){const cover=node.cloneNode(false);cover.classList.replace('qr-private','qr-private-cover');cover.removeAttribute('srcset');cover.src=qrCoverUrl;cover.alt='QRを隠しています';qrOriginals.set(cover,node);node.replaceWith(cover)}
  else if(!hidden&&node.classList.contains('qr-private-cover')){const original=qrOriginals.get(node);if(original)node.replaceWith(original)}
 }
}
