function updateSelection(){app.querySelectorAll('.compact-card').forEach(b=>{let i=items.find(i=>i.id===b.dataset.item);let picked=slots[active][i?.cat]?.id===i?.id;b.classList.toggle('selected',picked);b.querySelector('[data-pick]')?.setAttribute('aria-pressed',String(picked))})}
