function itemCard(i,wish){if(!wish)return `<article class="card compact-card ${i.cat!=='アクセ'?'large-piece':''} ${slots[active][i.cat]?.id===i.id?'selected':''}" data-item="${i.id}"><button class="item-image" data-pick="${i.id}" aria-pressed="${slots[active][i.cat]?.id===i.id}" aria-label="${esc(i.name)}を選択">${i.image?`<img loading="lazy" src="${i.image}" alt="${esc(i.name)}" draggable="false">`:icon(i.cat)}<span class="compact-name">${esc(i.name)}</span></button>${i.fav||i.fav2||i.fav3?`<button class="corner-heart" data-fav="${i.id}" aria-label="${esc(i.name)}のお気に入り"><svg class="favorite-gem" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 8 7 3h10l4 5-9 13Z" fill="#a8e8fa" stroke="#369ac1" stroke-width="1.2"/><path d="M3 8h18M7 3l3 5 2 13 2-13 3-5" fill="none" stroke="#51b3d1" stroke-width="1"/></svg></button>`:''}${isWanted(i)?`<span class="item-wish-badge ${wishState(i)===2?'gold-heart':''}">♥</span>`:''}</article>`;return `<article class="card"><button class="item-image" data-edit="${i.id}" aria-label="${esc(i.name)}を編集">${i.image?`<img loading="lazy" src="${i.image}" alt="${esc(i.name)}">`:icon(i.cat)}</button><strong>${esc(i.name)}</strong><small>${LETTER[i.cat]} · ${esc(i.cardId||i.cat)}</small><div class="card-actions"><button data-fav="${i.id}" aria-label="お気に入り">${i.fav||i.fav2||i.fav3?'💎':'◇'}</button><button data-edit="${i.id}" aria-label="編集">${icon('edit')}</button><button data-acquire="${i.id}">QRを追加</button></div></article>`}
function quickRows(root){if(!root.classList.contains('quick-view'))return;const cards=[...root.querySelectorAll('.compact-card')],expanded=cards.findIndex(c=>c.classList.contains('quick-expanded')),base=Math.max(24,(root.clientWidth-12)/3*.20),rows=Math.ceil(cards.length/3);root.style.gridTemplateRows=['auto',...Array.from({length:rows},(_,i)=>i===Math.floor(expanded/3)&&expanded>=0?Math.max(base,cards[expanded].offsetHeight)+'px':base+'px')].join(' ')}
function bindLongPress(root){root.querySelectorAll('[data-pick]').forEach(b=>{let timer,held=false,start;const cancel=()=>{clearTimeout(timer);timer=null};b.onpointerdown=e=>{if(e.button!==0)return;held=false;start=[e.clientX,e.clientY];timer=setTimeout(()=>{held=true;itemMenu(items.find(i=>i.id===b.dataset.pick));navigator.vibrate?.(12)},550)};b.onpointermove=e=>{if(start&&Math.hypot(e.clientX-start[0],e.clientY-start[1])>9)cancel()};b.onpointercancel=cancel;b.onpointerup=cancel;b.onpointerleave=cancel;b.oncontextmenu=e=>{e.preventDefault();held=true;cancel();itemMenu(items.find(i=>i.id===b.dataset.pick))};b.onclick=e=>{e.preventDefault();if(held){held=false;return}let i=items.find(i=>i.id===b.dataset.pick);if(quickView&&quickExpanded!==i.id){quickExpanded=i.id;root.querySelectorAll('.quick-expanded').forEach(e=>e.classList.remove('quick-expanded'));b.closest('.compact-card').classList.add('quick-expanded');quickRows(root);return}quickExpanded=null;b.closest('.compact-card').classList.remove('quick-expanded');quickRows(root);slots[active]=pick(slots[active],structuredClone(i));recordLook();persist();renderStyling();updateSelection()};b.onkeydown=e=>{if(e.key==='F10'&&e.shiftKey){e.preventDefault();itemMenu(items.find(i=>i.id===b.dataset.pick))}}})}
