function catalogBadges(c){let n=c.parts.filter(p=>items.some(i=>sameCard(i,p)&&inCloset(i))).length,w=c.parts.filter(p=>items.some(i=>sameCard(i,p)&&isWanted(i))).length;return `${n?`<span class="registered">✓ ${n}/${c.parts.length}登録済み</span>`:''}${w?`<span class="registered wish-badge">♡ ${w}ほしい</span>`:''}`}
