async function addWishes(coords){if(catalogBusy)return false;catalogBusy=true;let button=modal.querySelector('#wantcatalog')||app.querySelector('#bulkwish');if(button)button.disabled=true;try{const existing=items.filter(i=>!isWanted(i)&&coords.some(c=>c.parts.some(p=>sameCard(i,p))));const missing=missingWishParts(coords,items);if(!missing.length&&!existing.length){toast('すでに登録済みです');return true}let records=existing.map(i=>setMembership(i,{wanted:true}));for(let p of missing){records.push(normalize({...p,id:uid(),image:await localImage(p.image||''),total:await localImage(p.total||''),wantedAt:Date.now(),updated:Date.now()}))}await saveItems(records);await refresh();updateCatalogBadges();toast(`♡ ${records.length}アイテムを追加しました`);return true}catch(e){toast(e.message||'追加できませんでした');return false}finally{catalogBusy=false;if(button?.isConnected)button.disabled=false}}
function catalogDetail(c,push=true){saveCatalogPosition();if(push){catalogHistory(true);history.pushState({page:'catalog',catalog:{...history.state.catalog},detail:c.id},'','#catalog')}show(`<div class="modal-head"><button id="catalogdetailback">← 戻る</button><h2>${esc(c.name)}</h2></div><p class="hint">${esc(c.editionLabel||'')}</p>${c.total?`<img class="total-image" src="${c.total}" alt="トータルコーデ画像">`:'<p>画像未取得</p>'}<div class="catalog-parts">${c.parts.map(p=>`<div>${p.image?`<img src="${p.image}" alt="${esc(p.cat+' '+p.cardId)}">`:icon(p.cat)}<b>${esc(p.cat)}</b><small>${esc(p.cardId)}</small><small>${esc(p.imageStatus)}</small><button class="part-wish" data-partwish="${esc(p.cardId)}">${partWishLabel(p.cardId)}</button></div>`).join('')}</div><div class="toolbar"><button id="registercatalog" class="primary">${icon('add')} アイテムを登録</button><button id="wantcatalog">♡ コーデ全体を欲しいに追加</button></div><p class="hint">©T-ARTS / 各権利者。QRは自分で追加してください。</p>`);bindAll('[data-partwish]',async d=>{await togglePartWish(c,d.partwish)},modal);on('#catalogdetailback',()=>history.back(),modal);on('#registercatalog',()=>selectOfficialCoordinate(c,true),modal);on('#wantcatalog',async()=>{if(await addWishes([c])){close();history.back()}},modal)}
async function backup(){const meta=await get('state','backupMeta');show(`<div class="modal-head"><h2>データの保存・復元</h2><button id="close">×</button></div><p>アイテム・画像・QR・メモ・ほしい・ベスト・配置・下書きをまとめて保存します。</p><p class="hint">${items.length}アイテム / ${bests.length}ベストコーデ${meta?`<br>前回の書き出し：${new Date(meta.at).toLocaleString('ja-JP')}`:''}</p><button id="exportdata" class="primary">① バックアップを作る</button><div id="backupready"></div><hr><label class="field"><span>復元するファイルを選ぶ</span><input id="importdata" type="file" accept=".json,application/json"></label><label class="check field"><input id="overwritebackup" type="checkbox">同じIDのデータを更新する</label><label class="check field"><input id="restorelook" type="checkbox">保存時のコーデ・下書きも読み込む</label><p class="hint">チェックなしなら、今あるデータを優先して追加します。復元で既存アイテムを削除しません。</p>`);on('#exportdata',async e=>{e.currentTarget.disabled=true;const ready=modal.querySelector('#backupready');ready.innerHTML='<p class="hint">画像とQRをまとめています…</p>';try{await persist();const payload=await inlineImages({format:'ribbon-closet',version:3,appVersion:9,createdAt:new Date().toISOString(),items,best:bests,state:await encodeProBackup(await all('state'))},localImage);const blob=new Blob([JSON.stringify(payload)],{type:'application/json'});const url=URL.createObjectURL(blob),name='ribbon-data-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';ready.innerHTML=`<p class="success">✓ バックアップを作成しました</p><div class="toolbar"><button id="sharebackup" class="primary">② 共有して「ファイル」に保存</button><a id="downloadbackup" class="button" href="${url}" download="${name}">ファイルをダウンロード</a></div><p class="hint">iPhone：共有画面で「ファイルに保存」→保存先を選んで「保存」。機種変更時はこのファイルを新しい端末で読み込みます。</p>`;const record=()=>write('state',[{id:'backupMeta',at:Date.now(),count:items.length}]);on('#downloadbackup',record,modal);on('#sharebackup',async()=>{try{const file=new File([blob],name,{type:'application/json'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Ribbon Closetのデータ'});await record()}else modal.querySelector('#downloadbackup').click()}catch(e){if(e.name!=='AbortError')toast('「ファイルをダウンロード」から保存してください')}},modal);modal.addEventListener('close',()=>setTimeout(()=>URL.revokeObjectURL(url),120000),{once:true})}catch(e){ready.innerHTML=`<p class="danger">${esc(e.message||'バックアップを作れませんでした')}</p>`}finally{if(modal.querySelector('#exportdata'))modal.querySelector('#exportdata').disabled=false}},modal);modal.querySelector('#importdata').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const data=validateBackup(JSON.parse(await file.text()));const overwrite=modal.querySelector('#overwritebackup').checked,restoreLook=modal.querySelector('#restorelook').checked;const plan=restorePlan(data,items,bests,overwrite);if(!confirm(`アイテム${plan.items.length}件、ベスト${plan.best.length}件を読み込みます。既存の更新${plan.updated}件、重複スキップ${plan.skipped}件。${restoreLook?'選択コーデ・下書きも復元します。':''}続けますか？`))return;const presentState=new Set((await all('state')).map(s=>s.id));const states=decodeProBackup(data.state||[]).filter(s=>['composer','registrationDraft','session'].includes(s.id)||s.id?.startsWith(DEFERRED_PREFIX)&&s.batch?.mode==='pro'&&(overwrite||!presentState.has(s.id)));const composer=states.find(s=>s.id==='composer');if(restoreLook&&composer&&(!Array.isArray(composer.slots)||composer.slots.length!==2))throw Error('保存されたコーデの形式が違います');const incoming=(data.state||[]).find(s=>s.id==='organization');const mergedOrg=mergeOrganization(organization,incoming,overwrite);const tx=db.transaction(['items','best','state'],'readwrite');for(const record of data.state||[])if(record.kind==='coordinate-record'&&(overwrite||!presentState.has(record.id)))tx.objectStore('state').put(record);tx.objectStore('state').put(mergedOrg);plan.items.map(normalize).forEach(i=>tx.objectStore('items').put(i));plan.best.forEach(b=>tx.objectStore('best').put(b));if(restoreLook)states.forEach(s=>tx.objectStore('state').put(s));await new Promise((r,j)=>{tx.oncomplete=r;tx.onerror=()=>j(tx.error);tx.onabort=()=>j(tx.error)});await refresh();if(restoreLook){if(composer){slots=composer.slots;active=composer.active||0;compare=!!composer.compare;editingBest=composer.editingBest||null}pendingDraft=states.find(s=>s.id==='registrationDraft')||null}lookHistory.reset(slots,compare,active);close();go('home');toast('復元しました。今あるデータは削除していません')}catch(e){toast(e.message||'読み込めませんでした')}}}
document.querySelector('#brand').innerHTML=icon('アクセ')+'<span>Ribbon Closet<small>ときめきコーデ帳</small></span>';document.querySelector('#brand').onclick=e=>{e.preventDefault();go('home')};document.querySelector('#backup').onclick=backup;document.querySelector('nav').innerHTML=[['home','home','ホーム'],['closet','ワンピース','Myクローゼット'],['register','add','登録'],['items','catalog','コーデアイテム'],['best','star','ベスト']].map(([p,k,t])=>`<button data-page="${p}">${icon(k)}<span>${t}</span></button>`).join('');document.querySelectorAll('nav [data-page]').forEach(b=>b.onclick=()=>{if(b.dataset.page==='register')registrationOrigin='closet';if(b.dataset.page==='items')itemView.mode='all';go(b.dataset.page)});
(async()=>{try{await initDB();await refresh();const saved=await get('state','composer');backgrounds=(await get('state','backgrounds'))?.sides||[null,null];pendingDraft=await get('state','registrationDraft');const previous=await get('state','session');if(organization.wishSort)wishFilter.sort=organization.wishSort;if(saved){slots=saved.slots||[{},{}];active=saved.active||0;compare=!!saved.compare;editingBest=saved.editingBest}else{let old=JSON.parse(localStorage.getItem('ribbon-chosen')||'{}');for(let c of CATS){let i=items.find(i=>i.id===old[c]);if(i)slots[0][c]=i}}lookHistory.reset(slots,compare,active);booted=true;if(previous?.page==='register'&&pendingDraft){resumeDraft();return}if(previous?.page==='closet'&&slots.some(s=>Object.keys(s).length))page='closet';history.replaceState({page},'','#'+page);render()}catch(e){console.error(e);app.innerHTML='<p class="notice">保存領域を開けませんでした。通常のSafariで開き直してください。</p>'}})();
const localizedImages=new Map();
async function localImage(src){if(localizedImages.has(src))return localizedImages.get(src);if(!src||src.startsWith('data:'))return src;if(!src.startsWith('/catalog/assets/'))throw Error('画像形式を確認してください');const response=await fetch(src);if(!response.ok)throw Error('画像を読み込めませんでした');let blob=await response.blob();return await new Promise((r,j)=>{let f=new FileReader();f.onload=()=>{localizedImages.set(src,f.result);r(f.result)};f.onerror=j;f.readAsDataURL(blob)})}

function nameHeight(entries){const c=document.createElement('canvas').getContext('2d');c.font='38px sans-serif';return entries.reduce((h,x)=>h+wrapText(c,LETTER[x.cat]+': '+x.item.name,850).length*48+12,50)}

function returnToCatalog(){catalogReturn=false;page='catalog';catalogHistory(true);render()}
const bestThumbCache=new Map();async function refreshBestThumbs(){for(const b of bests){try{const key=b.id+':'+b.updated;if(!bestThumbCache.has(key)){const cv=await combinedCanvas(b.slots,b.compare,false,false,b.backgrounds||[]);const t=document.createElement('canvas');const scale=700/cv.height;t.width=Math.round(cv.width*scale);t.height=700;t.getContext('2d').drawImage(cv,0,0,t.width,t.height);bestThumbCache.set(key,t.toDataURL('image/png'))}const el=app.querySelector(`[data-best="${b.id}"] img`);if(el)el.src=bestThumbCache.get(key)}catch{}}}
window.addEventListener('popstate',async e=>{if(modal.open)modal.close();const state=e.state||{page:'home'};if(state.page==='catalog'){catalogReturn=false;if(state.catalog)Object.assign(catalogState,state.catalog);page='catalog';await catalogPage();if(state.detail){const c=allCatalog.find(c=>c.id===state.detail);if(c)catalogDetail(c,false)}}else{page=state.page||'home';if(page==='register'){if(pendingDraft){batch=structuredClone(pendingDraft.batch);stage=pendingDraft.stage||1;editingItem=pendingDraft.editingItem||null;draftSuppressed=false}else page='home'}render()}});
history.replaceState({page:'home'},'','#home');

async function ensureCatalog(){if(!catalogIndex.length)catalogIndex=await(await fetch('/catalog/index.json')).json();return loadAllCatalog()}
function partWishLabel(card){const i=items.find(i=>sameCard(i,{cardId:card}));return i&&wishState(i)===2?'♥ 特に欲しい':i&&isWanted(i)?'♥ 欲しい':'♡ 欲しい'}
async function togglePartWish(c,card){if(catalogBusy)return;const existing=items.find(i=>sameCard(i,{cardId:card}));try{if(existing){await updateItem(existing,{wishState:(wishState(existing)+1)%3});updateCatalogBadges()}else await addWishes([{...c,parts:c.parts.filter(p=>cardKey(p.cardId)===cardKey(card)),originalParts:c.parts}]);modal.querySelectorAll('[data-partwish]').forEach(b=>b.textContent=partWishLabel(b.dataset.partwish))}catch(e){toast(e.message)}}
async function openRelated(item,nextStage=1){if(!item)return;try{await ensureCatalog();const coord=relatedCoordinate(item,allCatalog);if(!coord){edit(item);stage=nextStage;registration();return}catalogReturn=false;editingItem=null;draftSuppressed=false;batch=buildRelatedDraft(item,coord,items);stage=nextStage;page='register';history.pushState({page:'register'},'','#register');render();window.scrollTo(0,0)}catch(e){toast('元のコーデを読み込めませんでした。もう一度お試しください')}}
let pendingDraft=null,booted=false,draftSuppressed=false;
function saveDraft(){if(!booted||draftSuppressed||page!=='register'||!batch.parts||batch.mode==='choose')return Promise.resolve();pendingDraft={id:'registrationDraft',batch:structuredClone(batch),stage,editingItem,catalogReturn,updated:Date.now()};const status=app.querySelector('.draft-indicator');if(status)status.textContent='入力内容を自動保存中…';return write('state',[pendingDraft]).then(()=>{if(status?.isConnected)status.textContent='✓ 入力内容を自動保存しました'}).catch(()=>toast('下書きを保存できませんでした'))}
async function saveRegistrationRecords(records){if(batch.reviewMode&&!catalogReturn&&!batch.related){batch.registrationSessionId||=uid();const draftId=batch.deferredId||('review-'+batch.registrationSessionId),copy=structuredClone(batch),entries=normalReviewEntries(),pending={};records=records.map(normalize);if(batch.mode==='individual')copy.rows=copy.rows.map((row,n)=>({...row,...records[n]}));else for(const [n,entry] of entries.entries())copy.parts[entry.key]={...copy.parts[entry.key],...records[n]};for(const [n,entry] of entries.entries()){const optional=(batch.deferredPending?.[entry.key]||[]).filter(k=>!['image','name','qr'].includes(k));const fields=[...optional,...(batch.reviewChoices?.[entry.key]!==false?missingFields(records[n]).filter(k=>batch.reviewFields?.[entry.key]?.[k]!==false):[])];if(fields.length)pending[entry.key]=fields}await commitRegistrationReview(db,{sessionId:batch.registrationSessionId,draftId,records,batch:copy,pending});return}if(!batch.deferredId)return saveItems(records);const result=await completeDeferred(db,batch.deferredId,records.map(normalize));if(result.alreadyCompleted)throw Error('この下書きは登録済みです。一覧を更新してください');return result}
async function clearDraft(){draftSuppressed=true;if(batch.deferredId){await deleteDeferredDraft(write,batch.deferredId);return}pendingDraft=null;await write('state',[],['registrationDraft'])}
function resumeDraft(){if(!pendingDraft){go('register');return}draftSuppressed=false;batch=structuredClone(pendingDraft.batch);stage=pendingDraft.stage||1;editingItem=pendingDraft.editingItem||null;catalogReturn=!!pendingDraft.catalogReturn;page='register';history.pushState({page:'register'},'','#register');render();window.scrollTo(0,0)}
function installHelp(){show(`<div class="modal-head"><h2>ホーム画面から使う</h2><button id="close">×</button></div><ol class="help-steps"><li>先に「データの保存・復元」でバックアップを作り、「ファイル」に保存する。</li><li>このアプリをiPhoneのSafariで開く。</li><li>共有ボタン（□↑）→「ホーム画面に追加」→「追加」。<small>「Webアプリとして開く」がある場合はオン。</small></li><li>追加されたRibbon Closetのアイコンをタップする。</li></ol><p class="notice">初回、アイコンから開いた画面にデータが見えない場合は、「データの保存・復元」から先ほどのファイルを読み込んでください。Safariとホーム画面版で保存場所が分かれることがあります。</p><p class="hint">以後はそのアイコンから使ってください。登録内容と前回のコーデは端末に自動保存します。ログインを求められた場合は同じChatGPTアカウントを使います。</p><div class="toolbar"><button id="helpbackup" class="primary">まずデータを保存</button><button id="copyappurl">アプリURLをコピー</button></div><a href="https://support.apple.com/ja-jp/guide/iphone/iphea86e5236/ios" target="_blank" rel="noopener">Appleの操作説明</a>`);on('#helpbackup',backup,modal);on('#copyappurl',async()=>{try{await navigator.clipboard.writeText(location.origin+'/');toast('URLをコピーしました')}catch{toast('Safariのアドレス欄からURLをコピーしてください')}},modal)}
