function individualItemsPage(){cancelSort();const canSort=itemView.sort==='original'&&!itemView.priorityFirst;if(!canSort)sortModes.items=false;app.innerHTML=`<section class="ci-item-page">${title('catalog','♡ コーデアイテム ♡')}<div class="tabs ci-modes"><button id="ci-coordinate-mode">コーデごと</button><button class="active" aria-pressed="true">アイテムごと</button></div><div class="tabs item-view-tabs">${[['all','すべて'],['wanted','ほしいもの']].map(([v,n])=>`<button data-itemmode="${v}" class="${itemView.mode===v?'active':''}">${n}</button>`).join('')}</div><div class="toolbar"><button id="newwish" class="primary">＋ ${itemView.mode==='wanted'?'欲しいアイテムを登録':'アイテムを登録'}</button></div><div class="tabs wish-tabs">${['',...CATS].map(c=>`<button data-wishcat="${c}" class="${itemView.cat===c?'active':''}" aria-label="${c||'全て'}">${c?icon(c):'✦'}<span>${c||'全て'}</span></button>`).join('')}</div><div class="search-row"><input id="wishsearch" type="search" value="${esc(itemView.query)}" placeholder="リスト内を検索"><button id="itemfilters">絞り込み</button><select id="wishsort" aria-label="並び替え">${[['original','オリジナル'],['new','追加した順・新しい順'],['old','追加した順・古い順'],['asc','名前順・昇順'],['desc','名前順・降順'],['priority','特に欲しいものを優先']].map(([v,n])=>`<option value="${v}" ${itemView.sort===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="wish-sort-action">${canSort?`<button id="sortwanted">${sortModes.items?'✓ 並び替え完了':'⠿ 並び替え'}</button>`:''}</div><div class="wish-priority"><label class="chip"><input id="priorityfirst" type="checkbox" ${itemView.priorityFirst?'checked':''}>✨ 特に欲しいを優先</label></div><p class="hint">${sortModes.items?'画像を長押しして動かします。離すとグリッドに収まります。':'画像タップで詳細。オリジナル順で並び替えできます。'}</p><div id="wishgrid" class="grid compact-grid wish-grid"></div>`;const draw=()=>{cancelSort();let rows=itemList(items,{...itemView,filter:itemView.filter},organization.itemOrder);app.querySelector('#wishgrid').innerHTML=rows.map(i=>itemView.mode==='all'?wishCard(i).replace('</button>',`<span class="ownership-label">${isOwned(i)?'所持':'未所持'}</span></button>`):wishCard(i)).join('')||'<div class="empty">♡<p>該当するアイテムはありません</p></div>';hydrateClosetThumbs(app.querySelector('#wishgrid'));if(sortModes.items)enableSort(app.querySelector('#wishgrid'),'items');else bindAll('[data-wishdetail]',d=>itemDetail(items.find(i=>i.id===d.wishdetail)));bindAll('[data-priority]',async d=>{const i=items.find(i=>i.id===d.priority);await updateItem(i,{wishState:(wishState(i)+1)%3});draw()})};on('#newwish',()=>{registrationOrigin=itemView.mode==='wanted'?'wanted':'closet';go('register')});on('#sortwanted',()=>{sortModes.items=!sortModes.items;itemsPage()});bindAll('[data-wishcat]',d=>{itemView.cat=d.wishcat;itemsPage()});app.querySelector('#wishsearch').oninput=e=>{itemView.query=e.target.value;draw()};app.querySelector('#wishsort').onchange=e=>{itemView.sort=e.target.value;itemsPage()};for(const[id,k]of [['priorityfirst','priorityFirst']])app.querySelector('#'+id).onchange=e=>{itemView[k]=e.target.checked;itemsPage()};bindAll('[data-itemmode]',d=>{itemView.mode=d.itemmode;sortModes.items=false;itemsPage()});on('#itemfilters',()=>{const v=itemView.filter;show(`<div class="modal-head"><h2>絞り込み</h2><button id="close">×</button></div>${favoriteUI(v)}<label class="chip"><input id="qronly" type="checkbox" ${v.qrOnly?'checked':''}>QR未登録は含まない</label>${attrUI(v,'filter')}<div class="toolbar"><button id="itemfilterclear">クリア</button><button id="closefilter" class="primary">完了</button></div>`);bindFavorites(modal,v,draw);modal.querySelector('#qronly').onchange=e=>{v.qrOnly=e.target.checked;draw()};bindAttrs(modal,'filter',v,draw);on('#itemfilterclear',()=>{itemView.filter={};close();itemsPage()},modal);on('#closefilter',()=>{close();itemsPage()},modal)});draw()}
function wanted(){cancelSort();const canSort=wishFilter.sort==='original'&&!wishFilter.priorityFirst;if(!canSort)sortModes.wanted=false;app.innerHTML=`${title('heart','欲しいものリスト')}<div class="toolbar"><button id="newwish" class="primary">＋ 欲しいアイテムを登録</button></div><div class="tabs wish-tabs">${['',...CATS].map(c=>`<button data-wishcat="${c}" class="${wishFilter.cat===c?'active':''}" aria-label="${c||'全て'}">${c?icon(c):'✦'}<span>${c||'全て'}</span></button>`).join('')}</div><div class="search-row"><input id="wishsearch" type="search" value="${esc(wishFilter.query)}" placeholder="リスト内を検索"><select id="wishsort" aria-label="並び替え">${[['original','オリジナル'],['new','追加した順・新しい順'],['old','追加した順・古い順'],['asc','名前順・昇順'],['desc','名前順・降順'],['priority','特に欲しいものを優先']].map(([v,n])=>`<option value="${v}" ${wishFilter.sort===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="wish-sort-action">${canSort?`<button id="sortwanted">${sortModes.wanted?'✓ 並び替え完了':'⠿ 並び替え'}</button>`:''}</div><div class="wish-priority"><label class="chip"><input id="priorityfirst" type="checkbox" ${wishFilter.priorityFirst?'checked':''}>✨ 特に欲しいを優先</label></div><p class="hint">${sortModes.wanted?'画像を長押しして動かします。離すとグリッドに収まります。':'画像タップで詳細。オリジナル順で並び替えできます。'}</p><div id="wishgrid" class="grid compact-grid wish-grid"></div>`;const draw=()=>{cancelSort();let rows=wishList(items,wishFilter);if(wishFilter.sort==='original'){rows=ordered(rows,organization.itemOrder);if(wishFilter.priorityFirst)rows.sort((a,b)=>(b.wishPriority||0)-(a.wishPriority||0))}if(wishFilter.sort==='priority')rows=ordered(rows,organization.itemOrder).sort((a,b)=>(b.wishPriority||0)-(a.wishPriority||0));app.querySelector('#wishgrid').innerHTML=rows.map(wishCard).join('')||'<div class="empty">♡<p>該当するアイテムはありません</p></div>';hydrateClosetThumbs(app.querySelector('#wishgrid'));if(sortModes.wanted)enableSort(app.querySelector('#wishgrid'),'wanted');else bindAll('[data-wishdetail]',d=>itemDetail(items.find(i=>i.id===d.wishdetail)));bindAll('[data-priority]',async d=>{const i=items.find(i=>i.id===d.priority);await updateItem(i,{wishState:(wishState(i)+1)%3});draw()})};on('#newwish',()=>{registrationOrigin='wanted';go('register')});on('#sortwanted',()=>{sortModes.wanted=!sortModes.wanted;wanted()});bindAll('[data-wishcat]',d=>{wishFilter.cat=d.wishcat;wanted()});app.querySelector('#wishsearch').oninput=e=>{wishFilter.query=e.target.value;draw()};app.querySelector('#wishsort').onchange=e=>{wishFilter.sort=e.target.value;organization.wishSort=wishFilter.sort;saveOrganization();wanted()};for(const[id,k]of [['priorityfirst','priorityFirst']])app.querySelector('#'+id).onchange=e=>{wishFilter[k]=e.target.checked;wanted()};draw()}
function wishCard(i){return `<article class="card compact-card ${i.cat!=='アクセ'?'large-piece':''} ${wishState(i)===2?'special-wish':''}" data-item="${i.id}"><button class="item-image" data-wishdetail="${i.id}" aria-label="${esc(i.name)}の詳細"><img src="${i.image}" alt="${esc(i.name)}" loading="lazy"><span class="compact-name">${esc(i.name)}</span></button>${isWanted(i)?`<button class="corner-heart ${wishState(i)===2?'gold-heart':''}" data-priority="${i.id}" aria-label="${esc(i.name)}の欲しい状態">♥</button>`:''}${i.fav||i.fav2||i.fav3?'<span class="item-favorite-star"><svg class="favorite-gem" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 8 7 3h10l4 5-9 13Z" fill="#a8e8fa" stroke="#369ac1" stroke-width="1.2"/><path d="M3 8h18M7 3l3 5 2 13 2-13 3-5" fill="none" stroke="#51b3d1" stroke-width="1"/></svg></span>':''}</article>`}
async function updateItem(i,changes){const prior=items.find(x=>x.id===i.id)||items.find(x=>sameCard(x,i));const r=normalize({...setMembership(prior||{...i,id:uid(),referenceOnly:undefined,inCloset:false,wanted:false},changes),updated:Date.now()});r.image=await localImage(r.image||'');r.total=await localImage(r.total||'');await saveItems([r]);await refresh();for(const target of [batch,pendingDraft?.batch]){if(!target)continue;for(const p of [...Object.values(target.parts||{}),...(target.rows||[])])if(p.id===r.id||sameCard(p,r))Object.assign(p,setMembership(p,changes))}if(pendingDraft)await write('state',[pendingDraft]);for(const s of slots)for(const c of CATS)if(s[c]?.id===r.id)s[c]={...r,...(s[c].pose?{pose:s[c].pose}:{}),...(s[c].shoeSizeVersion?{shoeSizeVersion:s[c].shoeSizeVersion}:{})};await persist();return r}
