function detailGroupChoice(item){const groups=groupCoordinates(items.filter(i=>i.coordinateGroupId&&!i.catalogRef?.id));show(`<div class="modal-head"><h2>関連コーデを変更</h2><button id="close">×</button></div><button id="dgnew">＋ 新しいコーデ</button><button id="dgnone">関連付けを解除</button><input id="dgsearch" placeholder="コーデ名を検索"><div id="dgresults"></div>`);const apply=async(id,name)=>{try{const next=await updateItem(item,{coordinateGroupId:id,coordinateGroupName:name});itemDetail(next);toast('関連コーデを更新しました')}catch{toast('保存できませんでした')}};const draw=()=>{const q=modal.querySelector('#dgsearch').value.trim().normalize('NFKC').toLowerCase();modal.querySelector('#dgresults').innerHTML=groups.map((g,n)=>{let name=g[0].coordinateGroupName||g[0].name;return name.normalize('NFKC').toLowerCase().includes(q)?`<button data-dg="${n}">${g.slice(0,3).map(i=>`<img src="${i.image||''}" alt="${esc(i.cat)}" style="width:48px;height:48px;object-fit:contain">`).join('')}${esc(name)} <small>${esc(g.map(i=>i.cat).join('・'))}</small></button>`:''}).join('');bindAll('[data-dg]',d=>{const g=groups[Number(d.dg)];apply(g[0].coordinateGroupId,g[0].coordinateGroupName||g[0].name)},modal)};modal.querySelector('#dgsearch').oninput=draw;draw();on('#dgnone',()=>apply('',''),modal);on('#dgnew',()=>{show(`<div class="modal-head"><h2>新しいコーデ</h2><button id="close">×</button></div><label class="field">コーデ名<input id="dgname" value="${esc(item.name)}" maxlength="100"></label><button id="dgsave">作成</button>`);on('#dgsave',()=>{const name=modal.querySelector('#dgname').value.trim();if(!name)return toast('コーデ名を入力してください');apply(uid(),name)},modal)},modal)}
