async function saveDetailSharedRemoval(original,draft){const sharedId=original.fullQR?.id;if(!sharedId)throw Error('共有するコーデを確認できません');const records=[];for(const item of items.filter(i=>i.id===original.id||i.fullQR?.id===sharedId)){const changed=item.id===original.id?{...draft,id:original.id}:clearQR(item,'full');const r=normalize(changed);r.image=await localImage(r.image||'');r.total=await localImage(r.total||'');records.push(r)}await saveItems(records);refreshSelected(records);await refresh();await persist()}
function refreshDetailOrigin(){const y=window.scrollY,scrollers=[...app.querySelectorAll('[id]')].map(el=>({id:el.id,x:el.scrollLeft,y:el.scrollTop}));if(page==='wanted')wanted();else if(page==='items')itemsPage();else if(page==='closet'){grid();renderStyling()}else if(page==='pro')proScreen();for(const pos of scrollers){const el=app.querySelector('#'+pos.id);if(el){el.scrollLeft=pos.x;el.scrollTop=pos.y}}window.scrollTo(0,y)}
function itemDetail(original,context={}){modal.classList.toggle('pro-no-qr-detail',context.allowQR===false);if(!original)return;if(context.editing)return itemDetailEdit(original,context);const i=context.save?original:items.find(x=>x.id===original.id)||items.find(x=>sameCard(x,original))||original,seq=++detailSeq,q=qrState(i),qr=i.qrPreference==='full'?(q.full?.image||q.individual?.image):(q.individual?.image||q.full?.image),saved=items.some(x=>x.id===i.id);show(`<div class="modal-head"><h2>${esc(i.name||'名称未登録')}</h2><button id="close" aria-label="閉じる">×</button></div><div class="detail-summary"><div><button id="detailimage" class="detail-edit-media">${i.image?`<img src="${esc(i.image)}" alt="${esc(i.name)}">`:'<span>NO PICTURE</span>'}</button><small>${esc(i.cat)} ${esc(i.cardId||'')}</small></div><button id="detailqr" aria-label="QRコードを拡大">${qr?`<img class="qr-private" src="${qr}" alt="QRコード"><small>${hasValidQR(i)?'QR登録済み':'QR未確認'}</small>`:`${icon('qr')}<span>QR未登録</span>`}</button></div>${favoriteUI(i)}<div class="detail-actions"><button id="detailwant" class="${wishState(i)===2?'gold-heart':isWanted(i)?'pink-heart':''}" aria-label="欲しい状態を切り替え">${isWanted(i)?'♥':'♡'}<small>${wishState(i)===2?'特に欲しい':isWanted(i)?'欲しい':'欲しいに追加'}</small></button><button id="itemedit" aria-label="編集">${icon('edit')}<small>${saved?'編集':'登録'}</small></button>${saved&&!context.save?'<button id="itemdelete" aria-label="削除">🗑<small>削除</small></button>':''}</div><div class="detail-membership"><button id="detailcloset" ${page==='items'?'style="display:none"':''}>${inCloset(i)?'✓ クローゼットに登録済み':'＋ クローゼットに登録'}</button><button id="detailaddqr">QRを登録</button></div>${saved&&!context.save&&!i.catalogRef?.id?'<button id="detailgroup">関連コーデを変更</button>':''}<div id="relatedarea"></div><div id="variantsarea"></div><details><summary>カラー・タグ・メモ</summary><p class="hint">${Object.keys(ATTR).map(k=>`${LABEL[k]}：${i[k]?.map(esc).join('・')||'未選択'}`).join('<br>')}</p><p class="hint">${esc(i.note||'')}</p></details>`);const act=async c=>{try{const r=context.save?await context.save(setMembership(structuredClone(i),c)):await updateItem(i,c);if(!context.save&&page==='wanted')wanted();if(!context.save&&page==='items')itemsPage();if(!context.save&&page==='closet')grid();itemDetail(r||{...i,...c},context)}catch(e){toast(e.message)}};on('#detailgroup',()=>detailGroupChoice(i),modal);const favoriteDraft={fav:!!i.fav,fav2:!!i.fav2,fav3:!!i.fav3};bindFavorites(modal,favoriteDraft,()=>act({...favoriteDraft}));on('#detailwant',()=>act({wishState:(wishState(i)+1)%3}),modal);on('#detailcloset',()=>{if(context.save)act({inCloset:!inCloset(i)});else if(!inCloset(i))act({inCloset:true});else closetRemoval(i,act)},modal);on('#detailimage',()=>itemDetailEdit(i,{...context,focusMedia:'image'}),modal);on('#detailqr',()=>{if(qr)qrDialog([i]);else itemDetailEdit(i,{...context,focusMedia:'qr'})},modal);on('#itemedit',()=>{if(saved||context.save)itemDetailEdit(i,context);else{close();referenceRegistration(i)}},modal);on('#detailaddqr',()=>itemDetailEdit(i,{...context,focusMedia:'qr'}),modal);on('#itemdelete',()=>deleteItem(i),modal);const fill=()=>{if(seq!==detailSeq||!modal.open||!modal.querySelector('#relatedarea'))return;for(const[id,title,rows]of [['relatedarea','関連アイテム',relatedItems(i,items,allCatalog)],['variantsarea','色違い',colorVariants(i,items)]]){const box=modal.querySelector('#'+id);if(rows.length<2){box.innerHTML='';continue}box.innerHTML=`<h3>${title}</h3><div class="relation-strip">${rows.map((r,n)=>`<button data-rel="${n}" aria-label="${esc(r.name)} ${esc(r.cat)}の詳細"><img src="${r.image}" alt="${esc(r.cat)}"><small>${esc(r.cat)}</small><span>${esc(r.name)}</span>${r.referenceOnly?'<small>未登録</small>':''}</button>`).join('')}</div>`;bindAll('[data-rel]',d=>context.openRelated?context.openRelated(rows[Number(d.rel)]):itemDetail(rows[Number(d.rel)]),box)}};fill();ensureCatalog().then(fill).catch(()=>{})}
function referenceRegistration(i){draftSuppressed=false;editingItem=null;batch={mode:'individual',parts:{},rows:[{...newRow(),...i,rowId:uid(),inCloset:true}],applyAll:true};stage=1;page='register';render()}

function refreshSelected(records){for(const s of slots)for(const c of CATS){const r=records.find(r=>r.id===s[c]?.id);if(r)s[c]={...r,...(s[c].pose?{pose:s[c].pose}:{}),...(s[c].shoeSizeVersion?{shoeSizeVersion:s[c].shoeSizeVersion}:{})}}
}

function closetRemoval(i,act){show(`<h2>Myクローゼットから外しますか？</h2><p>このアイテムをMyクローゼットから外しますか？</p><p>アイテムの登録情報は削除されません。欲しいものリストに登録している場合、その状態も維持されます。</p><div class="toolbar"><button id="cancelremove">キャンセル</button><button id="confirmremove">クローゼットから外す</button></div>`);on('#cancelremove',()=>itemDetail(i),modal);on('#confirmremove',()=>act({inCloset:false}),modal)}

let closetThumbObserver;function hydrateClosetThumbs(root){closetThumbObserver?.disconnect();const apply=async img=>{const src=img.getAttribute('src');try{const crop=await bitmap(src);if(img.isConnected&&img.getAttribute('src')===src)img.src=crop.url}catch{}};if(!('IntersectionObserver'in window)){root.querySelectorAll('.large-piece img').forEach(apply);return}closetThumbObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){closetThumbObserver.unobserve(e.target);apply(e.target)}},{root,rootMargin:'80px'});root.querySelectorAll('.large-piece img').forEach(img=>closetThumbObserver.observe(img))}

let bestQuery={nameIn:'',nameOut:'',itemIn:'',itemOut:'',cats:[]},bestSearchY=0;
function bestSearch(){cancelSort();app.innerHTML=`<button id="closebestsearch" class="close-best-search" aria-label="検索を閉じる">×</button>${title('star','ベストコーデ検索')}<section class="panel best-search-form"><fieldset><legend>ベストコーデ名</legend><label>含む<input data-query="nameIn" value="${esc(bestQuery.nameIn)}" placeholder="含む言葉"></label><label>含まない<input data-query="nameOut" value="${esc(bestQuery.nameOut)}" placeholder="除きたい言葉"></label></fieldset><fieldset><legend>使用アイテム名</legend><label>含む<input data-query="itemIn" value="${esc(bestQuery.itemIn)}" placeholder="含む言葉"></label><label>含まない<input data-query="itemOut" value="${esc(bestQuery.itemOut)}" placeholder="除きたい言葉"></label><div class="tabs">${CATS.map(c=>`<button data-searchcat="${c}" class="${bestQuery.cats.includes(c)?'active':''}" aria-pressed="${bestQuery.cats.includes(c)}">${icon(c)}<span>${c}</span></button>`).join('')}</div></fieldset><button id="clearbestsearch">条件をクリア</button></section><p id="bestsearchcount"></p><div class="best-grid" id="bestsearchgrid"></div>`;on('#closebestsearch',()=>go(bestSearchReturn));const draw=()=>{const rows=ordered(bests.filter(b=>matchesBest(b,bestQuery)),organization.bestOrder);app.querySelector('#bestsearchcount').textContent=rows.length+'件';app.querySelector('#bestsearchgrid').innerHTML=rows.map(b=>`<button class="best-card" data-best="${b.id}" aria-label="${esc(b.name)}の詳細"><img src="${b.thumb}" alt="コーデのプレビュー"></button>`).join('')||'<p>該当するコーデがありません</p>';bindAll('[data-best]',d=>{bestSearchY=window.scrollY;bestDetail(bests.find(b=>b.id===d.best))});refreshBestThumbs()};app.querySelectorAll('[data-query]').forEach(e=>e.oninput=()=>{bestQuery[e.dataset.query]=e.value;draw()});bindAll('[data-searchcat]',(d,e)=>{bestQuery.cats=bestQuery.cats.includes(d.searchcat)?bestQuery.cats.filter(x=>x!==d.searchcat):[...bestQuery.cats,d.searchcat];e.classList.toggle('active',bestQuery.cats.includes(d.searchcat));e.setAttribute('aria-pressed',String(bestQuery.cats.includes(d.searchcat)));draw()});on('#clearbestsearch',()=>{bestQuery={nameIn:'',nameOut:'',itemIn:'',itemOut:'',cats:[]};bestSearch()});draw();requestAnimationFrame(()=>window.scrollTo(0,bestSearchY))}

function urlImportPage(){urlImportDispose=mountURLImport({root:app,esc,relay:'https://ribbon-url-image-relay.divinebud10.chatgpt.site',onSave:async rows=>{const result=await addImportedImages(db,rows);await refresh();return result},onBack:()=>{page='register';render()}})}
